import { formatCurrency } from '@/lib/utils'
import type { ProjectsStats } from '@/lib/projects/queries'

interface ProjectsQuickStatsProps {
  stats: ProjectsStats
}

export function ProjectsQuickStats({ stats }: ProjectsQuickStatsProps) {
  const { activeCount, depositPoolCents, avgCompletionPct } = stats

  const depositFormatted =
    depositPoolCents > 0 ? formatCurrency(depositPoolCents) : '$0'
  const completionFormatted =
    avgCompletionPct > 0 ? `${avgCompletionPct}%` : '—'

  return (
    <div
      className="flex flex-col sm:flex-row sm:items-center gap-1 sm:gap-0 text-sm text-[var(--color-stone)]"
      data-testid="projects-quick-stats"
    >
      {/* Active */}
      <span className="flex items-baseline gap-1">
        <span className="font-bold tabular-nums text-[var(--color-onyx)]" style={{ fontVariantNumeric: 'tabular-nums' }}>
          {activeCount}
        </span>
        <span className="font-medium">active</span>
      </span>

      {/* Separator */}
      <span className="hidden sm:inline mx-2 text-[var(--color-stone)]/50" aria-hidden="true">·</span>

      {/* Deposit pools */}
      <span className="flex items-baseline gap-1">
        <span className="font-bold tabular-nums text-[var(--color-onyx)]" style={{ fontVariantNumeric: 'tabular-nums' }}>
          {depositFormatted}
        </span>
        <span className="font-medium">in deposit pools</span>
      </span>

      {/* Separator */}
      <span className="hidden sm:inline mx-2 text-[var(--color-stone)]/50" aria-hidden="true">·</span>

      {/* Avg completion */}
      <span className="flex items-baseline gap-1">
        <span className="font-bold tabular-nums text-[var(--color-onyx)]" style={{ fontVariantNumeric: 'tabular-nums' }}>
          {completionFormatted}
        </span>
        <span className="font-medium">avg completion</span>
      </span>
    </div>
  )
}

'use client'

import { useCallback } from 'react'
import { X } from 'lucide-react'
import { cn } from '@/lib/utils'
import { PROJECT_STYLES, STYLE_LABELS, PLACEMENT_PRESETS } from '@/lib/projects/schemas'
import type { ProjectStyle } from '@/lib/projects/schemas'
import type { ProjectStatus } from '@/lib/projects/queries'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface FilterClient {
  id: string
  first_name: string
  last_name: string | null
}

interface Artist {
  id: string
  display_name: string
}

interface ProjectFiltersProps {
  activeStatuses: ProjectStatus[]
  activeArtistId: string | null
  activeStyles: ProjectStyle[]
  activePlacements: string[]
  activeClientIds: string[]
  artists: Artist[]
  clients: FilterClient[]
  showArchived?: boolean
  onStatusToggle: (status: ProjectStatus) => void
  onArtistToggle: (artistId: string) => void
  onStyleToggle: (style: ProjectStyle) => void
  onPlacementToggle: (placement: string) => void
  onClientToggle: (clientId: string) => void
  onToggleShowArchived: () => void
  onClear: () => void
}

// ─── Constants ────────────────────────────────────────────────────────────────

export type { ProjectStatus }

const STATUS_LABELS: Record<ProjectStatus, string> = {
  planning: 'Planning',
  deposit_paid: 'Deposit Paid',
  active: 'Active',
  healing: 'Healing',
  completed: 'Completed',
  on_hold: 'On Hold',
  cancelled: 'Archived',
}

const DEFAULT_STATUSES: ProjectStatus[] = [
  'planning',
  'deposit_paid',
  'active',
  'healing',
  'completed',
  'on_hold',
]

const ARCHIVED_STATUS: ProjectStatus = 'cancelled'

export const ALL_STATUSES: ProjectStatus[] = [...DEFAULT_STATUSES, ARCHIVED_STATUS]
export const BOARD_STATUSES: ProjectStatus[] = ['planning', 'deposit_paid', 'active', 'healing', 'completed']
export { STATUS_LABELS }

// Placements are the PLACEMENT_PRESETS enum values (free-text still searchable via search input)
const PLACEMENT_FILTER_OPTIONS = PLACEMENT_PRESETS.slice() as readonly string[]

// ─── Filter chip ──────────────────────────────────────────────────────────────

function FilterChip({
  label,
  active,
  onToggle,
}: {
  label: string
  active: boolean
  onToggle: () => void
}) {
  if (active) {
    return (
      <button
        onClick={onToggle}
        className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-medium bg-foreground text-background transition-colors"
        aria-pressed="true"
      >
        {label}
        <X className="h-2.5 w-2.5" aria-hidden="true" />
      </button>
    )
  }

  return (
    <button
      onClick={onToggle}
      className={cn(
        'px-2.5 py-1 rounded-full text-[11px] font-medium border border-border',
        'text-muted-foreground hover:text-foreground hover:border-foreground/30 transition-colors'
      )}
      aria-pressed="false"
    >
      {label}
    </button>
  )
}

// ─── Section separator ────────────────────────────────────────────────────────

function Separator() {
  return (
    <span className="h-3 w-px bg-border shrink-0" role="separator" aria-hidden="true" />
  )
}

// ─── Active filter pill (removable) ──────────────────────────────────────────

interface ActiveFilterPillProps {
  label: string
  onRemove: () => void
}

function ActiveFilterPill({ label, onRemove }: ActiveFilterPillProps) {
  return (
    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-medium bg-[var(--color-onyx)]/8 text-[var(--color-onyx)] border border-[var(--color-border)]">
      {label}
      <button
        onClick={onRemove}
        className="ml-0.5 rounded-full hover:bg-[var(--color-onyx)]/10 transition-colors p-0.5"
        aria-label={`Remove ${label} filter`}
      >
        <X className="h-2.5 w-2.5" aria-hidden="true" />
      </button>
    </span>
  )
}

// ─── Filters ──────────────────────────────────────────────────────────────────

export function ProjectFilters({
  activeStatuses,
  activeArtistId,
  activeStyles,
  activePlacements,
  activeClientIds,
  artists,
  clients,
  showArchived = false,
  onStatusToggle,
  onArtistToggle,
  onStyleToggle,
  onPlacementToggle,
  onClientToggle,
  onToggleShowArchived,
  onClear,
}: ProjectFiltersProps) {
  const hasActiveFilters =
    activeStatuses.length > 0 ||
    activeArtistId !== null ||
    activeStyles.length > 0 ||
    activePlacements.length > 0 ||
    activeClientIds.length > 0

  const handleStatusToggle = useCallback(
    (s: ProjectStatus) => { onStatusToggle(s) },
    [onStatusToggle]
  )

  const visibleStatuses = showArchived ? ALL_STATUSES : DEFAULT_STATUSES

  // Build active pills for the removable pills row
  const activeStatusPills = activeStatuses.map((s) => ({
    key: `status-${s}`,
    label: STATUS_LABELS[s],
    onRemove: () => onStatusToggle(s),
  }))

  const activeArtistPill = activeArtistId
    ? artists.find((a) => a.id === activeArtistId)
    : null

  const activeStylePills = activeStyles.map((s) => ({
    key: `style-${s}`,
    label: STYLE_LABELS[s],
    onRemove: () => onStyleToggle(s),
  }))

  const activePlacementPills = activePlacements.map((p) => ({
    key: `placement-${p}`,
    label: p,
    onRemove: () => onPlacementToggle(p),
  }))

  const activeClientPills = activeClientIds.map((id) => {
    const c = clients.find((cl) => cl.id === id)
    const label = c
      ? `${c.first_name}${c.last_name ? ` ${c.last_name}` : ''}`
      : id.slice(0, 8)
    return {
      key: `client-${id}`,
      label,
      onRemove: () => onClientToggle(id),
    }
  })

  const allActivePills = [
    ...activeStatusPills,
    ...(activeArtistPill
      ? [{ key: `artist-${activeArtistId}`, label: activeArtistPill.display_name, onRemove: () => onArtistToggle(activeArtistId!) }]
      : []),
    ...activeStylePills,
    ...activePlacementPills,
    ...activeClientPills,
  ]

  return (
    <div className="space-y-2">
      {/* Filter chips row */}
      <div className="flex flex-wrap items-center gap-1.5" aria-label="Filter by status">
        {/* Status chips */}
        {visibleStatuses.map((s) => (
          <FilterChip
            key={s}
            label={STATUS_LABELS[s]}
            active={activeStatuses.includes(s)}
            onToggle={() => handleStatusToggle(s)}
          />
        ))}

        {/* Show / hide archived toggle */}
        <button
          onClick={onToggleShowArchived}
          className="px-2.5 py-1 rounded-full text-[11px] font-medium border border-dashed border-border text-muted-foreground hover:text-foreground hover:border-foreground/30 transition-colors"
        >
          {showArchived ? 'Hide archived' : '+ Archived'}
        </button>

        {/* Artist chips (separator) */}
        {artists.length > 0 && (
          <>
            <Separator />
            {artists.map((a) => (
              <FilterChip
                key={a.id}
                label={a.display_name}
                active={activeArtistId === a.id}
                onToggle={() => onArtistToggle(a.id)}
              />
            ))}
          </>
        )}

        {/* Style chips */}
        {PROJECT_STYLES.length > 0 && (
          <>
            <Separator />
            {PROJECT_STYLES.map((s) => (
              <FilterChip
                key={s}
                label={STYLE_LABELS[s]}
                active={activeStyles.includes(s)}
                onToggle={() => onStyleToggle(s)}
              />
            ))}
          </>
        )}

        {/* Placement chips */}
        {PLACEMENT_FILTER_OPTIONS.length > 0 && (
          <>
            <Separator />
            {PLACEMENT_FILTER_OPTIONS.map((p) => (
              <FilterChip
                key={p}
                label={p}
                active={activePlacements.includes(p)}
                onToggle={() => onPlacementToggle(p)}
              />
            ))}
          </>
        )}

        {/* Client chips */}
        {clients.length > 0 && (
          <>
            <Separator />
            {clients.map((c) => {
              const label = `${c.first_name}${c.last_name ? ` ${c.last_name}` : ''}`
              return (
                <FilterChip
                  key={c.id}
                  label={label}
                  active={activeClientIds.includes(c.id)}
                  onToggle={() => onClientToggle(c.id)}
                />
              )
            })}
          </>
        )}

        {/* Clear all */}
        {hasActiveFilters && (
          <button
            onClick={onClear}
            className="px-2.5 py-1 text-[11px] text-muted-foreground hover:text-foreground transition-colors"
          >
            Clear all filters
          </button>
        )}
      </div>

      {/* Active filter pills row — shows only when filters are active */}
      {allActivePills.length > 0 && (
        <div className="flex flex-wrap items-center gap-1.5" aria-label="Active filters">
          <span className="text-[11px] text-[var(--color-stone)] font-medium mr-0.5">Filtered by:</span>
          {allActivePills.map((pill) => (
            <ActiveFilterPill
              key={pill.key}
              label={pill.label}
              onRemove={pill.onRemove}
            />
          ))}
        </div>
      )}
    </div>
  )
}

