/**
 * Set the privacy level on a single progress photo.
 * privacy: 'studio' | 'client' | 'public'
 * Default on upload: 'studio'.
 *
 * NOTE: `privacy` column is in the DB but not yet in the generated types file.
 * Using a targeted cast here. Regenerate types with `pnpm db:types` after next Dato run.
 * Role: studio member with write access (owner | admin | artist).
 */
export async function setPhotoPrivacyAction({
  photoId,
  privacy,
}: {
  photoId: string
  privacy: PhotoPrivacy
}): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { error: 'Not authenticated' }
  if (!canWrite(auth.role as ReadRole)) return { error: 'Insufficient permissions' }

  const parsed = setPrivacySchema.safeParse({ photoId, privacy })
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  const supabase = await createClient()

  const resolved = await resolvePhoto(supabase, parsed.data.photoId, auth.studioId)
  if (!resolved) return { error: 'Photo not found' }

  // Cast to bypass generated types which don't yet include the privacy column.
  // Safe: the column exists in the DB migration — regenerate types to remove cast.
  const { error: updateError } = await (supabase
    .from('project_progress_photos')
    .update({ privacy: parsed.data.privacy } as Record<string, string>)
    .eq('id', parsed.data.photoId) as unknown as Promise<{ error: { message: string } | null }>)

  if (updateError) {
    logger.error({ updateError, photoId }, 'setPhotoPrivacyAction failed')
    return { error: 'Failed to update privacy setting' }
  }

  revalidatePath(`/projects/${resolved.projectId}`)
  return {}
}

