'use client'

import { useState, useTransition, useRef } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Camera, Plus, Trash2, Download, Loader2, Pencil, Check, Lock, Eye, Users } from 'lucide-react'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import {
  Dialog,
  DialogContent,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { cn, formatDate } from '@/lib/utils'
import {
  updateProjectPhotoCaptionAction,
  deleteProjectPhotoAction,
  setPhotoPrivacyAction,
} from '@/app/(app)/projects/photo-actions'
import type { PhotoPrivacy } from '@/app/(app)/projects/photo-actions'
import type { ProjectWithSessions, ProjectProgressPhoto, ProjectPhotoKind } from '@/lib/projects/queries'

// ─── Privacy helpers ───────────────────────────────────────────────────────────

const PRIVACY_OPTIONS: { value: PhotoPrivacy; label: string; icon: React.ReactNode }[] = [
  { value: 'studio', label: 'Studio', icon: <Lock className="h-3 w-3" /> },
  { value: 'client', label: 'Client', icon: <Users className="h-3 w-3" /> },
  { value: 'public', label: 'Public', icon: <Eye className="h-3 w-3" /> },
]

function privacyIcon(privacy: PhotoPrivacy | null | undefined) {
  const p = privacy ?? 'studio'
  if (p === 'client') return <Users className="h-3 w-3" />
  if (p === 'public') return <Eye className="h-3 w-3" />
  return <Lock className="h-3 w-3" />
}

// Extend ProjectProgressPhoto to allow privacy field (column exists in DB, not yet in generated types)
type PhotoWithPrivacy = ProjectProgressPhoto & { privacy?: PhotoPrivacy | null }

// ─── Privacy segmented control ────────────────────────────────────────────────

interface PrivacyControlProps {
  photoId: string
  currentPrivacy: PhotoPrivacy | null | undefined
  onChanged: (next: PhotoPrivacy) => void
}

function PrivacyControl({ photoId, currentPrivacy, onChanged }: PrivacyControlProps) {
  const [saving, setSaving] = useState(false)
  const effective = currentPrivacy ?? 'studio'

  const handleChange = async (next: PhotoPrivacy) => {
    if (next === effective || saving) return
    setSaving(true)
    const result = await setPhotoPrivacyAction({ photoId, privacy: next })
    setSaving(false)
    if (result.error) {
      toast.error(result.error)
      return
    }
    onChanged(next)
  }

  return (
