const STALLED_PLANNING_DAYS = 45

function isClientSideStalled(project: ProjectListItem): boolean {
  // Client-side fallback: if status is 'planning' and no activity for 45+ days,
  // show stalled pill even when stalled_at IS NULL (cron hasn't run yet).
